         pod=dict(bank=["mercy", "nikah", "mahr", "parents", "Janazah"], sents=["Allah placed affection and ____ in marriage.", "The marriage contract is the ____.", "The ____ is a gift to the bride.", "Muslims must treat their ____ well.", "The funeral prayer is the ____."],
                  key="1) mercy · 2) nikah · 3) mahr · 4) parents · 5) Janazah", frames=["Families are important because …", "At a birth, Muslims …"]),
